import React, { useRef, useEffect } from 'react';
import './inputitems.css';

const InputItem = ({ label, placeholder = ' ', name, onChange, type = 'text', isTextArea = false, className, value }) => {
    const textAreaRef = useRef(null);

    // Auto-grow textarea
    useEffect(() => {
        if (isTextArea && textAreaRef.current) {
            textAreaRef.current.style.height = "auto"; // Reset height
            textAreaRef.current.style.height = `${textAreaRef.current.scrollHeight}px`; // Expand to fit content
        }
    }, [value]); // Runs whenever the value changes

    return (
        <div className={`row ${className}`}> 
            <div className='input'>
                {!isTextArea ? (
                    <input 
                        onChange={onChange} 
                        placeholder={placeholder} 
                        name={name} 
                        type={type} 
                        value={value} // Bind value to the state
                    />
                ) : (
                    <textarea 
                        ref={textAreaRef} // Attach ref to textarea
                        onChange={onChange} 
                        placeholder={placeholder} 
                        name={name}
                        value={value} // Bind value to the state
                        style={{
                            width: "100%",
                            minHeight: "40px",
                            overflow: "hidden",
                            resize: "none",
                            fontSize: "16px",
                            padding: "10px",
                            borderRadius: "5px",
                            border: "1px solid #ccc",
                        }}
                    ></textarea>
                )}
                <label>{label}</label>
            </div>
        </div>
    );
};

export default InputItem;
